// Shared failure path (docs/N8N.md WF-05). Every other workflow's error branch calls this
// via an Execute Workflow node, passing whatever context it has. This normalises that into
// one shape, writes one line to the execution log for observability, and hands back a
// standardised error envelope the caller returns to Next.js.
const inp = $json && typeof $json === 'object' ? $json : {};
const body = inp.body && typeof inp.body === 'object' ? inp.body : inp;

const workflow = String(body.workflow || body.source || 'unknown');
const stage = String(body.stage || body.node || 'unknown');
const rawErr = body.error ?? body.message ?? body.reason ?? 'unspecified error';
const message = (typeof rawErr === 'string' ? rawErr : JSON.stringify(rawErr)).slice(0, 500);
const requestId = String(body.requestId || body.request_id || $execution.id || '');

let statusCode = Number(body.statusCode || body.status || 0);
if (!Number.isInteger(statusCode) || statusCode < 400 || statusCode > 599) statusCode = 502;

const code = String(body.code || (statusCode === 400 ? 'invalid_request' : 'workflow_failed'));

console.log('[WF-05] ' + JSON.stringify({ workflow, stage, code, statusCode, requestId, message }));

return [{ json: { workflow, stage, code, statusCode, requestId, message, at: new Date().toISOString() } }];

// The envelope the calling workflow should return from its Respond node, with the HTTP
// status to use. Kept deliberately small and free of clinic data.
const e = $json;
return [{ json: {
  statusCode: e.statusCode,
  response: {
    ok: false,
    error: e.code,
    message: e.message,
    workflow: e.workflow,
    stage: e.stage,
    requestId: e.requestId
  }
} }];
